#include "ombra/server/policy.hpp"

#include <algorithm>

#include "ombra/search/layout.hpp"
#include "preset_table.hpp"  // generated by CMake from core/params/ckks_presets.json

namespace ombra::server {

const PresetInfo* find_preset(const std::string& name) {
  for (const auto& p : generated::kPresets)
    if (name == p.name) return &p;
  return nullptr;
}

std::size_t max_filter_fields_for(const PresetInfo& p) {
  return search::max_filter_fields(p.first_mod_bits, p.scale_bits);
}

Status validate_spec(const storage::CollectionSpec& s) {
  const auto bad = [](Err c, const char* m) { return Status{c, m}; };
  if (s.api_version != kApiVersion) return bad(Err::UnsupportedVersion, "unsupported api_version");
  if (s.name.empty()) return bad(Err::InvalidArgument, "collection name is empty");
  if (s.name.size() > kMaxNameBytes) return bad(Err::SizeLimit, "collection name is too long");
  const PresetInfo* preset = find_preset(s.preset);
  if (!preset) return bad(Err::InvalidArgument, "unknown preset");
  if (s.dimension == 0) return bad(Err::InvalidArgument, "dimension must be positive");
  if (s.key_tag.empty()) return bad(Err::InvalidArgument, "key_tag is empty");
  if (s.key_tag.size() > kMaxKeyTagBytes) return bad(Err::SizeLimit, "key_tag is too long");
  if (s.cluster_count == 0 || s.cluster_count > kMaxClusterCount)
    return bad(Err::InvalidArgument, "cluster_count out of range");
  if (s.security_level > 3) return bad(Err::InvalidArgument, "unknown security level");
  try {
    (void)search::make_layout(s, preset->ring_dim, max_filter_fields_for(*preset));
  } catch (const search::LayoutError& e) {
    // The layout messages are fixed texts naming limits only.
    return bad(Err::InvalidFilterLayout, e.what());
  }
  return {};
}

}  // namespace ombra::server
